void CRndSeed::SetSeed(unsigned s){rndacc=s?s:0xA341316CU;rndvls=s^0xC8013EA4U;}unsigned CRandom::Seed(const char*s){unsigned h=2166136261U;if(s)while(*s){h^=static_cast<unsigned char>(*s++);h*=16777619U;}return h;}
unsigned CRandom::lattice_(CRndSeed&s){unsigned x=s.rndacc;x^=x<<13;x^=x>>17;x^=x<<5;s.rndacc=x;s.rndvls+=0x9E3779B9U;return x+s.rndvls;}unsigned CRandom::lattice2_(CRndSeed&s){return lattice_(s);}unsigned CRandom::lattice3_(CRndSeed&s){return lattice_(s);}unsigned CRandom::lattice4_(CRndSeed&s){return lattice_(s);}unsigned CRandom::lattice8_(CRndSeed&s){return lattice_(s);}unsigned CRandom::lattice9_(CRndSeed&s){return lattice_(s);}unsigned CRandom::lattice27_(CRndSeed&s){return lattice_(s);}
float CRandom::reale_(CRndSeed&s){return (lattice_(s)>>8)*(1.0F/16777216.0F);}double CRandom::lreale_(CRndSeed&s){return lattice_(s)*(1.0/4294967296.0);}float CRandom::reale_(CRndSeed&s,float m){return reale_(s)*m;}double CRandom::lreale_(CRndSeed&s,double m){return lreale_(s)*m;}float CRandom::realg_(CRndSeed&s){float u1=std::max(reale_(s),1e-7F),u2=reale_(s);return std::sqrt(-2*std::log(u1))*std::cos(6.283185307F*u2);}double CRandom::lrealg_(CRndSeed&s){return realg_(s);}float CRandom::realg_(CRndSeed&s,float m,float v){return m+v*realg_(s);}double CRandom::lrealg_(CRndSeed&s,double m,double v){return m+v*lrealg_(s);}
void CRandom::array_(float*a,unsigned n,CRndSeed&s){for(unsigned i=0;i<n;++i)a[i]=reale_(s);}void CRandom::array_(double*a,unsigned n,CRndSeed&s){for(unsigned i=0;i<n;++i)a[i]=lreale_(s);}void CRandom::arrayp_(float*a,unsigned n,CRndSeed&s){array_(a,n,s);std::sort(a,a+n);}void CRandom::arrays_(float*a,unsigned n,CRndSeed&s){array_(a,n,s);for(unsigned i=0;i<n;++i)a[i]=2*a[i]-1;}void CRandom::arraye_(float*a,unsigned n,CRndSeed&s){array_(a,n,s);}void CRandom::arraye_(double*a,unsigned n,CRndSeed&s){array_(a,n,s);}void CRandom::arrayg_(float*a,unsigned n,CRndSeed&s){for(unsigned i=0;i<n;++i)a[i]=realg_(s);}void CRandom::shuffle_(void*p,unsigned n,unsigned width,CRndSeed&s){auto*b=static_cast<unsigned char*>(p);for(unsigned i=n;i>1;--i){unsigned j=lattice_(s)%i;for(unsigned k=0;k<width;++k)std::swap(b[(i-1)*width+k],b[j*width+k]);}}void CRandom::crypt_(void*p,unsigned n,CRndSeed&s){auto*b=static_cast<unsigned char*>(p);for(unsigned i=0;i<n;++i)b[i]^=static_cast<unsigned char>(lattice_(s));}C2Vector CRandom::C2Vector_(CRndSeed&s){return {2*reale_(s)-1,2*reale_(s)-1};}C3Vector CRandom::C3Vector_(CRndSeed&s){C3Vector v(2*reale_(s)-1,2*reale_(s)-1,2*reale_(s)-1);if(v.SquaredMag())v.Normalize();return v;}float CRandom::noise_(float x,CRndSeed&s){unsigned save=s.rndacc;s.rndacc^=unsigned(std::floor(x)*2654435761U);float r=2*reale_(s)-1;s.rndacc=save;return r;}float CRandom::turbulence_(float x,unsigned oct,CRndSeed&s){float sum=0,w=1;for(unsigned i=0;i<oct;++i){sum+=std::fabs(noise_(x,s))*w;x*=2;w*=.5F;}return sum;}
